import java.util.*;

class Solution {
  private static final char[] MOVES = {'U', 'D', 'L', 'R'};
  private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
  private static final int OFFSET = 100, SIZE = 201;
  private int[][] cost; // cost of entering a cell, 0 = unknown / blocked
  private int targetR = -1, targetC = -1;

  public int findShortestPath(GridMaster master) {
    cost = new int[SIZE][SIZE];
    cost[OFFSET][OFFSET] = -1; // start: known open, never re-entered for its cost
    explore(master, OFFSET, OFFSET);
    if (targetR < 0) return -1;
    int[][] dist = new int[SIZE][SIZE];
    for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[2], b[2]));
    dist[OFFSET][OFFSET] = 0;
    pq.add(new int[] {OFFSET, OFFSET, 0});
    while (!pq.isEmpty()) {
      int[] c = pq.poll();
      if (c[2] > dist[c[0]][c[1]]) continue;
      if (c[0] == targetR && c[1] == targetC) return c[2];
      for (int[] d : DIRS) {
        int x = c[0] + d[0], y = c[1] + d[1];
        if (x < 0 || y < 0 || x >= SIZE || y >= SIZE || cost[x][y] <= 0) continue;
        if (c[2] + cost[x][y] < dist[x][y]) {
          dist[x][y] = c[2] + cost[x][y];
          pq.add(new int[] {x, y, dist[x][y]});
        }
      }
    }
    return -1;
  }

  private void explore(GridMaster master, int r, int c) {
    if (master.isTarget()) {
      targetR = r;
      targetC = c;
    }
    for (int k = 0; k < 4; k++) {
      int x = r + DIRS[k][0], y = c + DIRS[k][1];
      if (x < 0 || y < 0 || x >= SIZE || y >= SIZE || cost[x][y] != 0 || !master.canMove(MOVES[k])) continue;
      cost[x][y] = master.move(MOVES[k]);
      explore(master, x, y);
      master.move(MOVES[k ^ 1]);
    }
  }
}
